export const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
export const round=n=>Math.round((n+Number.EPSILON)*100)/100;
export const amount=s=>{let v=s.trim().replace(/[$€£\s]/g,'').replace('−','-');let neg=/^\(.*\)$/.test(v);v=v.replace(/[()]/g,'');if(/,\d{2}$/.test(v))v=v.replace(/\./g,'').replace(',','.');else v=v.replace(/,/g,'');let n=Number(v);return Number.isFinite(n)?(neg?-n:n):NaN};
export const isMoney=s=>/^[-−]?\s*[$€£]?\s*\(?\d[\d.,]*[.,]\d{2}\)?$/.test(s.trim());
export const datePattern=/\b(?:\d{4}-\d{1,2}-\d{1,2}|\d{1,2}[\/-]\d{1,2}(?:[\/-]\d{2,4})?|\d{1,2} de (?:enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre) de \d{4})\b/gi;
const months=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
export function isoDate(s,year=2026,format='MDY'){if(!s)return '';let m=s.trim().match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);let y,mo,d;if(m){[,y,mo,d]=m}else{m=s.trim().match(/^(\d{1,2}) de (\w+) de (\d{4})$/i);if(m){d=m[1];mo=months.indexOf(m[2].toLowerCase())+1;y=m[3]}else{m=s.trim().match(/^(\d{1,2})[\/-](\d{1,2})(?:[\/-](\d{2,4}))?$/);if(!m)return '';mo=format==='MDY'?m[1]:m[2];d=format==='MDY'?m[2]:m[1];y=m[3]?(m[3].length===2?'20'+m[3]:m[3]):year}}let date=new Date(Date.UTC(+y,+mo-1,+d));if(date.getUTCFullYear()!==+y||date.getUTCMonth()!==+mo-1||date.getUTCDate()!==+d)return '';return `${y}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
export function replaceDates(text,iso,format='MDY'){const [y,m,d]=iso.split('-');return text.replace(datePattern,old=>{if(old==='24/7'||!isoDate(old,+y,format))return old;if(/ de /i.test(old))return `${+d} de ${months[+m-1]} de ${y}`;if(/^\d{4}-/.test(old))return iso;let sep=old.includes('/')?'/':'-';let parts=old.split(/[\/-]/);let padded=parts[0].length===2||parts[1].length===2;let a=format==='MDY'?m:d,b=format==='MDY'?d:m;if(!padded){a=String(+a);b=String(+b)}return [a,b,...(parts.length===3?[parts[2].length===2?y.slice(2):y]:[])].join(sep)})}
export function fieldsFromText(text,viewport,pageIndex,util){return text.items.filter(i=>i.str?.trim()).map((i,n)=>{const t=util.transform(viewport.transform,i.transform);const size=Math.hypot(t[2],t[3]);const style=text.styles[i.fontName]||{};return {id:`p${pageIndex}f${n}`,page:pageIndex,pdfX:i.transform[4],pdfY:i.transform[5],original:i.str,value:i.str,x:t[4],baseline:t[5],top:t[5]-size*(style.ascent??.8),width:Math.max(i.width,2),height:size,size,family:style.fontFamily||'sans-serif',angle:Math.atan2(t[1],t[0])}})}
export function groupLines(fields){let lines=[];for(const f of [...fields].sort((a,b)=>a.baseline-b.baseline||a.x-b.x)){let l=lines.find(l=>Math.abs(l.y-f.baseline)<1.8);if(!l){l={y:f.baseline,fields:[]};lines.push(l)}l.fields.push(f)}for(const l of lines)l.fields.sort((a,b)=>a.x-b.x);return lines.sort((a,b)=>a.y-b.y)}
export function parseDocument(pages,format='MDY'){
 const fields=pages.flatMap(p=>p.fields),whole=fields.map(f=>f.original).join(' '),year=+(whole.match(/\b20\d{2}\b/)?.[0]||new Date().getFullYear());
 const doc={id:crypto.randomUUID(),name:'',pages,rows:[],bank:false,opening:0,year,summary:{},history:[]};
 let headers;
 for(const p of pages){const dep=p.fields.find(f=>/^Depósitos\/$|^Deposits\/?$/i.test(f.original.trim())),debit=p.fields.find(f=>/^Retiros\/$|^Withdrawals\/?$/i.test(f.original.trim())),bal=p.fields.find(f=>/^Saldo$|^Balance$/i.test(f.original.trim())&&dep&&Math.abs(f.baseline-dep.baseline)<5);if(dep&&debit&&bal){headers={deposit:dep.x,debit:debit.x,balance:bal.x,baseline:dep.baseline};doc.bank=true;break}}
 if(doc.bank){
  for(const p of pages){const lines=groupLines(p.fields);const localHeader=p.fields.find(f=>/^Depósitos\/$|^Deposits\/?$/i.test(f.original.trim()));if(!localHeader)continue;let current=null;
   for(const l of lines){if(l.y<localHeader.baseline+12)continue;let ds=l.fields.find(f=>f.x<p.width*.19&&/^\d{1,2}\/\d{1,2}(?:\/\d{2,4})?$/.test(f.original.trim()));const nums=l.fields.filter(f=>isMoney(f.original)&&f.x>headers.deposit-60);if(ds&&nums.length){let dep=nums.find(f=>f.x<(headers.deposit+headers.debit)/2),deb=nums.find(f=>f.x>=(headers.deposit+headers.debit)/2&&f.x<(headers.debit+headers.balance)/2),bal=nums.find(f=>f.x>=(headers.debit+headers.balance)/2);let description=l.fields.filter(f=>f.x>p.width*.2&&f.x<headers.deposit-20&&!nums.includes(f));current={id:crypto.randomUUID(),date:isoDate(ds.original,year,format),description:description.map(f=>f.original.trim()).join(' '),deposit:dep?amount(dep.original):0,debit:deb?amount(deb.original):0,balance:bal?amount(bal.original):null,fields:{date:ds.id,deposit:dep?.id,debit:deb?.id,balance:bal?.id,description:description.map(f=>f.id)},page:p.index,selected:false,dirty:false};doc.rows.push(current)}else if(l.fields.some(f=>/^Totales$|^Totals$/i.test(f.original.trim()))){doc.summary.tableDeposits=nums[0]?.id;doc.summary.tableDebits=nums[1]?.id;current=null;break}else if(current&&l.y<localHeader.baseline+500){let more=l.fields.filter(f=>f.x>p.width*.2&&f.x<headers.deposit-20);if(more.length){current.description+=' '+more.map(f=>f.original.trim()).join(' ');current.fields.description.push(...more.map(f=>f.id))}}
   }
  }
  for(const p of pages)for(const l of groupLines(p.fields)){let label=l.fields.find(f=>/^Saldo inicial al|^Beginning balance/i.test(f.original.trim()));let nums=l.fields.filter(f=>isMoney(f.original));if(label&&nums.length){let f=nums.find(f=>f.x>label.x+label.width);if(f){doc.opening=amount(f.original);doc.summary.opening=f.id}}
   for(const [key,re]of [['deposits',/^Depósitos\/Adiciones\s*$/i],['debits',/^Retiros\/Deducciones\s*$/i],['closing',/^Saldo final al/i]]){let label=l.fields.find(f=>re.test(f.original.trim()));if(label){let f=nums.find(f=>f.x>label.x+label.width&&f.x<label.x+300);if(f)doc.summary[key]=f.id}}
  }
 }else{for(const p of pages)for(const l of groupLines(p.fields)){let nums=l.fields.filter(f=>isMoney(f.original));let ds=l.fields.find(f=>isoDate(f.original,year,format));let text=l.fields.map(f=>f.original).join(' ');if(!nums.length||/\b(total|subtotal|saldo|balance|tax|impuesto)\b/i.test(text)||(!ds&&l.fields.length<2))continue;let total=nums.at(-1),desc=l.fields.filter(f=>f!==total&&f!==ds&&!isMoney(f.original));doc.rows.push({id:crypto.randomUUID(),date:ds?isoDate(ds.original,year,format):'',description:desc.map(f=>f.original.trim()).join(' '),qty:1,price:amount(total.original),fields:{date:ds?.id,amount:total.id,description:desc.map(f=>f.id)},page:p.index,selected:false,dirty:false})}for(const p of pages)for(const l of groupLines(p.fields)){if(l.fields.some(f=>/^total(?:\s+general)?\s*:?$/i.test(f.original.trim()))){let f=l.fields.filter(f=>isMoney(f.original)).at(-1);if(f)doc.summary.total=f.id}}}
 return doc;
}
export const getField=(doc,id)=>doc.pages.flatMap(p=>p.fields).find(f=>f.id===id);
export function setField(doc,id,value){const f=getField(doc,id);if(f)f.value=String(value)}
export function formattedAmount(value,old){let clean=old?.trim()||'';let comma=/,\d{2}$/.test(clean);let n=new Intl.NumberFormat(comma?'de-DE':'en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(value);if(clean.includes('$'))n=value<0?'-$'+n.replace(/^-/,''):'$'+n;return n}
export function totals(doc){if(doc.bank){let deposits=round(doc.rows.reduce((s,r)=>s+r.deposit,0)),debits=round(doc.rows.reduce((s,r)=>s+r.debit,0));return {deposits,debits,total:round(doc.opening+deposits-debits)}}return {total:round(doc.rows.reduce((s,r)=>s+round(r.qty*r.price),0))}}
export function recalc(doc,paint=true){if(doc.bank){let bal=doc.opening;for(const r of doc.rows){bal=round(bal+r.deposit-r.debit);r.calculatedBalance=bal;if(paint&&r.fields.balance){let f=getField(doc,r.fields.balance);setField(doc,f.id,formattedAmount(bal,f.original))}}}if(paint){let t=totals(doc);for(const [key,value]of Object.entries({opening:doc.opening,deposits:t.deposits,debits:t.debits,closing:t.total,tableDeposits:t.deposits,tableDebits:t.debits,total:t.total})){let f=getField(doc,doc.summary[key]);if(f&&value!==undefined)setField(doc,f.id,formattedAmount(key==='debits'&&f.original.trim().startsWith('-')?-value:value,f.original))}}return totals(doc)}
export function syncRow(doc,row,key,format='MDY'){
 row.dirty=true;
 if(key==='date'&&row.fields.date){let f=getField(doc,row.fields.date);setField(doc,f.id,replaceDates(f.original,row.date,format))}
 if(doc.bank&&(key==='deposit'||key==='debit')){let f=getField(doc,row.fields[key]);if(f)setField(doc,f.id,formattedAmount(row[key],f.original));else if(row[key]!==0&&doc.pdf){throw Error('Este campo no existe en el PDF. Edita el importe en su columna original.')};recalc(doc)}
 if(!doc.bank&&(key==='qty'||key==='price')){let f=getField(doc,row.fields.amount);if(f)setField(doc,f.id,formattedAmount(round(row.qty*row.price),f.original));recalc(doc)}
 if(key==='description'){let ids=row.fields.description||[];if(ids.length){setField(doc,ids[0],row.description);for(const id of ids.slice(1))setField(doc,id,'')}}
}
export function applyBatchDate(doc,iso,format='MDY',selected=false){if(!/^\d{4}-\d{2}-\d{2}$/.test(iso)||!isoDate(iso))throw Error('Elige una fecha válida.');let count=0;let ids=selected?new Set(doc.rows.filter(r=>r.selected).flatMap(r=>[r.fields.date,...(r.fields.description||[])])):null;for(const p of doc.pages)for(const f of p.fields){if(ids&&!ids.has(f.id))continue;let value=replaceDates(f.value,iso,format);if(value!==f.value){f.value=value;count++}}for(const r of doc.rows)if(!selected||r.selected){r.date=iso;r.dirty=true;const desc=(r.fields.description||[]).map(id=>getField(doc,id)?.value||'').join(' ');if(desc)r.description=desc}return count}
export function snapshot(doc){doc.history.push({rows:structuredClone(doc.rows),values:doc.pages.flatMap(p=>p.fields).map(f=>[f.id,f.value]),opening:doc.opening});if(doc.history.length>30)doc.history.shift()}
export function undo(doc){let s=doc.history.pop();if(!s)return false;doc.rows=s.rows;doc.opening=s.opening;for(const [id,value]of s.values)setField(doc,id,value);recalc(doc,false);return true}
export function exportRows(docs){const data=[['Documento','Fecha','Descripción','Cantidad','Precio','Depósitos','Retiros','Saldo / Total']];for(const doc of docs){recalc(doc,false);for(const r of doc.rows)data.push([doc.name,r.date,r.description,doc.bank?'':r.qty,doc.bank?'':r.price,doc.bank?r.deposit:'',doc.bank?r.debit:'',doc.bank?r.calculatedBalance:round(r.qty*r.price)]);let t=totals(doc);data.push([doc.name,'','TOTAL','','',t.deposits??'',t.debits??'',t.total])}return data}
export function csvText(data){return '\ufeff'+data.map(row=>row.map(v=>{let s=String(v??'');if(typeof v==='string'&&/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(',')).join('\r\n')}
export function xlsText(data){const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'');let rows=data.map((r,n)=>'<Row>'+r.map(v=>`<Cell${n===0?' ss:StyleID="Header"':''}><Data ss:Type="${typeof v==='number'?'Number':'String'}">${escape(v??'')}</Data></Cell>`).join('')+'</Row>').join('');return '<?xml version="1.0" encoding="UTF-8"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Header"><Font ss:Bold="1" ss:Color="#FFFFFF"/><Interior ss:Color="#12382F" ss:Pattern="Solid"/></Style></Styles><Worksheet ss:Name="Statements"><Table><Column ss:Width="180"/><Column ss:Width="85"/><Column ss:Width="420"/>'+rows+'</Table></Worksheet></Workbook>'}

export function paintChanges(ctx,page,scale){for(const f of page.fields){if(f.value===f.original)continue;ctx.save();ctx.scale(scale,scale);ctx.translate(f.x,f.baseline);ctx.rotate(f.angle||0);const top=f.top-f.baseline;ctx.fillStyle='#fff';ctx.fillRect(-.5,top-.8,f.width+1,f.height+2);if(f.value){let family=f.family==='serif'?'Times New Roman,serif':'Arial,sans-serif';let size=f.size;ctx.font=`${size}px ${family}`;const measured=ctx.measureText(f.value).width;if(measured>f.width)size*=f.width/measured;ctx.font=`${size}px ${family}`;ctx.fillStyle='#111';ctx.textBaseline='alphabetic';let x=0;if(/^[-$\d.,\s]+$/.test(f.original.trim()))x=Math.max(0,f.width-ctx.measureText(f.value).width);ctx.fillText(f.value,x,0)}ctx.restore()}}
